{
  "items": [
    {
      "name": "Finset.mulConst_le_divConst_sq",
      "module_name": "Mathlib.Combinatorics.Additive.DoublingConst",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} [inst : CommGroup G] [inst_1 : DecidableEq G] {A : Finset G}, A.mulConst A ≤ A.divConst A ^ 2"
    },
    {
      "name": "Finset.divConst_le_mulConst_sq",
      "module_name": "Mathlib.Combinatorics.Additive.DoublingConst",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} [inst : Group G] [inst_1 : DecidableEq G] {A : Finset G}, A.divConst A ≤ A.mulConst A ^ 2"
    },
    {
      "name": "lt_of_mul_self_lt_mul_self₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : LinearOrder M₀] [PosMulStrictMono M₀] {a b : M₀} [MulPosMono M₀],\n  0 ≤ b → a * a < b * b → a < b"
    },
    {
      "name": "tendsto_apply_add_mul_sq_div_sub",
      "module_name": "Mathlib.Analysis.Calculus.Monotone",
      "kind": "theorem",
      "type": "∀ {f : ℝ → ℝ} {x a c d : ℝ} {l : Filter ℝ},\n  l ≤ nhdsWithin x {x}ᶜ →\n    Filter.Tendsto (fun y => (f y - d) / (y - x)) l (nhds a) →\n      Filter.Tendsto (fun y => y + c * (y - x) ^ 2) l l →\n        Filter.Tendsto (fun y => (f (y + c * (y - x) ^ 2) - d) / (y - x)) l (nhds a)"
    },
    {
      "name": "mabs_div_lt_of_one_le_of_lt",
      "module_name": "Mathlib.Algebra.Order.Group.Abs",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} [inst : CommGroup G] [inst_1 : LinearOrder G] [IsOrderedMonoid G] {a b n : G},\n  1 ≤ a → a < n → 1 ≤ b → b < n → |a / b|ₘ < n"
    }
  ]
}
